UPDATE log_user_login SET
  logout_status = #{logoutStatus,jdbcType=CHAR},
  logout_time   = #{logoutTime,jdbcType=TIMESTAMP},
  logout_desc   = #{logoutDesc,jdbcType=VARCHAR}
WHERE user_id = #{userId,jdbcType=VARCHAR}
  AND logout_status IS NULL
  AND login_status = #{loginStatus,jdbcType=CHAR}
  AND (login_mode IS NULL OR login_mode != 'ops')

