SELECT

FROM log_user_login


    AND user_id = #{userId,jdbcType=VARCHAR}


    AND token = #{token,jdbcType=VARCHAR}


    AND user_name = #{userName,jdbcType=VARCHAR}


    AND institute_id = #{instituteId,jdbcType=VARCHAR}


    AND login_ip LIKE CONCAT(#{loginIp,jdbcType=VARCHAR}, '%')


    AND login_status = #{loginStatus,jdbcType=CHAR}


    AND login_time BETWEEN #{loginTimeStart,jdbcType=TIMESTAMP} AND #{loginTimeEnd,jdbcType=TIMESTAMP}
